public class ResilientProductionAiService
{
    private readonly IChatClient _primaryClient;   // Azure OpenAI GPT-4o (PTU)
    private readonly IChatClient _secondaryClient; // Azure OpenAI Secondary Region (Pay-Go)
    private readonly IChatClient _localFallback;   // Local Small Model / Canned Rule Engine
    private readonly ILogger<ResilientProductionAiService> _logger;

    public async Task<AiExecutionResult> ExecuteWithFallbackAsync(
        IList<ChatMessage> messages,
        ChatOptions options,
        CancellationToken ct = default)
    {
        try
        {
            // Attempt 1: Primary production model
            var response = await _primaryClient.CompleteAsync(messages, options, ct);
            return new AiExecutionResult(response.Message.Text!, QualityTier.PrimaryHighFidelity);
        }
        catch (Exception ex) when (ex is HttpRequestException or TimeoutException)
        {
            _logger.LogWarning(ex, "Primary AI model endpoint failed. Failing over to secondary region.");

            try
            {
                // Attempt 2: Secondary region failover
                var secondaryResponse = await _secondaryClient.CompleteAsync(messages, options, ct);
                return new AiExecutionResult(secondaryResponse.Message.Text!, QualityTier.SecondaryFailover);
            }
            catch (Exception secEx)
            {
                _logger.LogError(secEx, "Secondary AI region also unreachable. Degrading to deterministic fallback.");

                // Attempt 3: Graceful degradation (safe static answer / offline intent resolution)
                return new AiExecutionResult(
                    "Our intelligent assistant is currently experiencing elevated latency. " +
                    "Your request has been queued for human specialist review.",
                    QualityTier.DegradedOfflineNotice);
            }
        }
    }
}
